//! An interrupted `version` run resumes from its checkpoint (ADR 13): resuming leaves exactly what an uninterrupted run
//! leaves, and a run whose inputs changed is refused with steps that undo it.
#![cfg(unix)]

use std::collections::BTreeMap;
use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

/// Lockfile tools that succeed without touching anything, except the one named by `FAIL_PROG`, which fails once per
/// `FAIL_FLAG` file. Cargo commands other than `update` run the real cargo, which workspace loading needs.
fn fake_tools(dir: &Path) -> PathBuf {
    let bin = dir.join("bin");
    fs::create_dir_all(&bin).unwrap();
    let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".to_string());
    for prog in ["cargo", "npm", "uv", "yarn", "pnpm", "bun"] {
        let script = format!(
            "#!/bin/sh\nif [ \"$FAIL_PROG\" = {prog} ] && [ ! -e \"$FAIL_FLAG\" ]; then touch \"$FAIL_FLAG\"; \
             echo simulated failure >&2; exit 1; fi\nif [ {prog} = cargo ] && [ \"$1\" != update ]; then exec \"{cargo}\" \
             \"$@\"; fi\nexit 0\n"
        );
        let path = bin.join(prog);
        fs::write(&path, script).unwrap();
        fs::set_permissions(&path, fs::Permissions::from_mode(0o755)).unwrap();
    }
    bin
}

fn git(root: &Path, args: &[&str]) -> String {
    let output = Command::new("git").args(args).current_dir(root).output().unwrap();
    assert!(
        output.status.success(),
        "git {args:?}: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).into_owned()
}

fn version(workspace: &Path, bin: &Path, fail: Option<(&str, &Path)>) -> Output {
    let path = format!("{}:{}", bin.display(), std::env::var("PATH").unwrap_or_default());
    let mut command = Command::new(env!("CARGO_BIN_EXE_callisto"));
    command
        .args(["--cwd", workspace.to_str().unwrap(), "version"])
        .env("PATH", path);
    if let Some((prog, flag)) = fail {
        command.env("FAIL_PROG", prog).env("FAIL_FLAG", flag);
    }
    command.output().unwrap()
}

fn write(root: &Path, path: &str, text: &str) {
    let path = root.join(path);
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(path, text).unwrap();
}

fn crate_at(root: &Path, dir: &str, version: &str, deps: &str) {
}

/// Writes a workspace's files into the directory it is given.
type Shape = fn(&Path);

struct Repo {
    _dir: tempfile::TempDir,
    root: PathBuf,
    workspace: PathBuf,
}

/// A committed repository built by `shape` in `subdir` of it; `uncommitted` stays out of the first commit.
fn repo(shape: Shape, subdir: &str, uncommitted: Option<&str>) -> Repo {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().join("repo");
    let workspace = if subdir.is_empty() {
        root.clone()
    } else {
        root.join(subdir)
    };
    fs::create_dir_all(&workspace).unwrap();
    callisto_fixtures::git::init_repo(&root);
    shape(&workspace);
    let held = uncommitted.map(|path| (workspace.join(path), fs::read(workspace.join(path)).unwrap()));
    if let Some((path, _)) = &held {
        fs::remove_file(path).unwrap();
    }
    git(&root, &["add", "-A"]);
    git(&root, &["commit", "-qm", "init"]);
    if let Some((path, bytes)) = held {
        fs::write(path, bytes).unwrap();
    }
    Repo {
        _dir: dir,
        root,
        workspace,
    }
}

/// Every file outside `.git`, plus the status and the index, so two trees compare exactly.
fn state(root: &Path) -> (BTreeMap<PathBuf, Vec<u8>>, String, String) {
        .unwrap()
        .permissions()
        .mode();
    assert_eq!(mode & 0o777, 0o444);
}

#[test]
fn a_workspace_named_with_leading_spaces_resumes_itself_not_its_sibling() {
    // The sibling has the same crates at the same versions and a different changeset, so resuming it would pass the
    // input checks and write its bump, notes and changelog into this workspace.
    assert_resume_matches(
        "space-prefixed workspace",
        cargo_cascade,
        "  release-work",
        "cargo",
        None,
        |repo| {
            let sibling = repo.root.join("release-work");
            cargo_cascade(&sibling);
            write(
                &sibling,
                ".changeset/one.md",
                "---\n\"a\": major\n---\n\nSibling break\n",
            );
            git(&repo.root, &["add", "-A"]);
            git(&repo.root, &["commit", "-qm", "sibling"]);
        },
    );
}

#[test]
fn a_checkout_with_crlf_line_endings_still_resumes() {
    let (_, resumed) = assert_resume_matches("crlf", cargo_cascade, "", "cargo", None, |repo| {
    write(ws, ".changeset/one.md", "---\n\"ui\": minor\n---\n\nUi change\n");
}

#[test]
fn a_manifest_edited_after_the_failure_refuses_the_resume() {
    let repo = repo(npm_range, "", None);
    let bin = fake_tools(repo.root.parent().unwrap());
    let flag = repo.root.parent().unwrap().join("failed-once");
    version(&repo.workspace, &bin, Some(("npm", &flag)));
    // Pinning the dependency changes what the plan would do; a resume must not run on the stale plan.
    let manifest = repo.workspace.join("js/app/package.json");
    let edited = "{\"name\":\"app\",\"version\":\"1.0.0\",\"dependencies\":{\"ui\":\"1.0.0\"}}\n";
    fs::write(&manifest, edited).unwrap();

    let out = version(&repo.workspace, &bin, None);

    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        !out.status.success() && stderr.contains("E340") && stderr.contains("js/app/package.json"),
        "{stderr}"
    );
    assert_eq!(fs::read_to_string(&manifest).unwrap(), edited);
}

#[test]
    assert!(changelog.contains("add f"), "{changelog}");
    assert!(
        !changelog.contains("index"),
        "the checkpoint's synthetic commit leaked into history: {changelog}"
    );
}

fn failed_cargo_run(repo: &Repo, bin: &Path) -> Output {
    let flag = repo.root.parent().unwrap().join("failed-once");
    version(&repo.workspace, bin, Some(("cargo", &flag)))
}

/// A run that cannot start (the changelog is ignored) must leave no checkpoint, so fixing `.gitignore` works.
#[test]
fn a_run_that_fails_before_writing_leaves_no_checkpoint() {
    let repo = repo(
        |ws| {
            cargo_cascade(ws);
            write(ws, ".gitignore", "CHANGELOG.md\n");
        },
        "",
        None,
    );
    let bin = fake_tools(repo.root.parent().unwrap());

    let first = version(&repo.workspace, &bin, None);

    assert!(
        String::from_utf8_lossy(&first.stderr).contains("E314"),
        "{}",
        String::from_utf8_lossy(&first.stderr)
    );
    assert!(
        !has_checkpoint(&repo.root),
        "a run that cannot start leaves no checkpoint"
    );
    write(&repo.workspace, ".gitignore", "");
    let second = version(&repo.workspace, &bin, None);
    assert!(second.status.success(), "{}", String::from_utf8_lossy(&second.stderr));
}

/// A changeset the user deletes after the interruption is a change, not the run's own consumption.
#[test]
fn a_changeset_deleted_by_hand_after_the_failure_refuses_the_resume() {
    let repo = repo(
        |ws| {
    git: &'g callisto_model::vcs::GitAccess<'r>,
    tree: std::path::PathBuf,
    _dir: tempfile::TempDir,
}

impl Drop for ResumeTree<'_, '_> {
    fn drop(&mut self) {
        self.git.remove_worktree(&self.tree).ok();
    }
}

/// Checks the checkpoint out in a throwaway worktree and loads the workspace there.
fn open_checkpoint_tree<'g, 'r>(
    git: &'g callisto_model::vcs::GitAccess<'r>,
    checkpoint: &callisto_model::vcs::Checkpoint,
    runner: &'r CliCommandRunner,
    global: &GlobalArgs,
) -> Result<
    (
        ResumeTree<'g, 'r>,
        callisto_graph::Workspace<'r, CliCommandRunner, ManifestWalkResolver>,
    ),
    CliError,
> {
    let dir = tempfile::tempdir().map_err(|source| CliError::Io { source, path: None })?;
    let tree = dir.path().join("tree");
    git.add_checkpoint_worktree(VERSION_CHECKPOINT, &tree, &checkpoint.facts.head)
        .map_err(GraphError::from)?;
    let resume = ResumeTree { git, tree, _dir: dir };
    let prefix = git.root_prefix().map_err(GraphError::from)?;
    let scratch = load_workspace(
        &GlobalArgs {
            cwd: resume.tree.join(prefix),
            ..global.clone()
        },
        runner,
    )?;
    Ok((resume, scratch))
}

